package data_structures.trees;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class BinarySearchTree {
public static class BSTNode<T>{public T value;public BSTNode<T> left,right;public BSTNode(T v){value=v;}}public static class Tree<T> implements Iterable<T>{private BSTNode<T> root;private int count;private final Comparator<T> compare;public Tree(){this(shared.Compare::defaultCompare);}public Tree(Comparator<T> c){compare=c;}public static <T> Tree<T> from(Iterable<T> a){return from(a,shared.Compare::defaultCompare);}public static <T> Tree<T> from(Iterable<T> a,Comparator<T> c){Tree<T> t=new Tree<>(c);for(T v:a)t.insert(v);return t;}public int size(){return count;}public BSTNode<T> rootNode(){return root;}public boolean insert(T v){if(root==null){root=new BSTNode<>(v);count++;return true;}BSTNode<T> n=root;while(true){int c=compare.compare(v,n.value);if(c==0)return false;if(c<0){if(n.left==null){n.left=new BSTNode<>(v);break;}n=n.left;}else{if(n.right==null){n.right=new BSTNode<>(v);break;}n=n.right;}}count++;return true;}public boolean has(T v){BSTNode<T> n=root;while(n!=null){int c=compare.compare(v,n.value);if(c==0)return true;n=c<0?n.left:n.right;}return false;}public boolean delete(T v){if(!has(v))return false;root=remove(root,v);count--;return true;}private BSTNode<T> remove(BSTNode<T> n,T v){if(n==null)return null;int c=compare.compare(v,n.value);if(c<0)n.left=remove(n.left,v);else if(c>0)n.right=remove(n.right,v);else{if(n.left==null)return n.right;if(n.right==null)return n.left;BSTNode<T> s=n.right;while(s.left!=null)s=s.left;n.value=s.value;n.right=remove(n.right,s.value);}return n;}public T min(){BSTNode<T> n=root;if(n==null)return null;while(n.left!=null)n=n.left;return n.value;}public T max(){BSTNode<T> n=root;if(n==null)return null;while(n.right!=null)n=n.right;return n.value;}public T floor(T v){BSTNode<T> n=root;T r=null;while(n!=null){int c=compare.compare(v,n.value);if(c==0)return n.value;if(c<0)n=n.left;else{r=n.value;n=n.right;}}return r;}public T ceil(T v){BSTNode<T> n=root;T r=null;while(n!=null){int c=compare.compare(v,n.value);if(c==0)return n.value;if(c>0)n=n.right;else{r=n.value;n=n.left;}}return r;}public int height(){return height(root);}private int height(BSTNode<T> n){return n==null?0:1+Math.max(height(n.left),height(n.right));}public List<T> toArray(){List<T> o=new ArrayList<>();walk(root,o);return o;}private void walk(BSTNode<T> n,List<T> o){if(n==null)return;walk(n.left,o);o.add(n.value);walk(n.right,o);}public Iterator<T> iterator(){return toArray().iterator();}}
}
